sketch:
// Buzzer & relay — two outputs that switch together.
//
// The buzzer shows its signal when pin 8 is high, and the relay's coil is
// energized when pin 7 is high. The relay contacts are not wired in this
// preset; the badge beside the relay shows the coil state.

void setup() {
  pinMode(7, OUTPUT);
  pinMode(8, OUTPUT);
}

void loop() {
  digitalWrite(7, HIGH);
  digitalWrite(8, HIGH);
  delay(300);
  digitalWrite(7, LOW);
  digitalWrite(8, LOW);
  delay(400);
}
